import {validNavigationAsset} from './navigation-mesh.js';
import {hasGameplayTag} from './scene-systems.js';
export async function runEnvironmentQuery(data,{origin,context=origin,forward=data?.plane==='XY'?[0,1,0]:[0,0,1],objects=[],trace=()=>false,project=p=>p,diagnostics}={}){
  if(!validNavigationAsset('environmentquery',data)||![origin,context,forward].every(v=>Array.isArray(v)&&v.length===3&&v.every(Number.isFinite)))throw Error('환경 질의 값 오류');const started=diagnostics?performance.now():0,candidates=[],flat=data.plane==='XY',distance=v=>flat?Math.hypot(v[0],v[1]):Math.hypot(...v),planePosition=(x,y)=>flat?[origin[0]+x,origin[1]+y,origin[2]]:[origin[0]+x,origin[1],origin[2]+y];
  if(data.generator==='actors'){for(const o of objects)if(o.poolActive!==false&&distance(o.position.map((v,i)=>v-origin[i]))<=data.radius)candidates.push({position:[...o.position],actor:o.id,tags:o.tags||[]});}
  else if(data.generator==='ring')for(let i=0;i<data.count;i++){const a=i/data.count*Math.PI*2;candidates.push({position:planePosition(Math.cos(a)*data.radius,Math.sin(a)*data.radius),actor:null,tags:[]});}
  else{const n=Math.floor(data.radius/data.spacing);if((n*2+1)**2>100000)throw Error('환경 질의 생성 예산 초과');for(let x=-n;x<=n;x++)for(let z=-n;z<=n;z++)if(Math.hypot(x,z)*data.spacing<=data.radius)candidates.push({position:planePosition(x*data.spacing,z*data.spacing),actor:null,tags:[]});}
  const retained=diagnostics?new Map():null;if(diagnostics){const limit=diagnostics.limit??4096;if(!Number.isInteger(limit)||limit<1||limit>100000)throw Error('EQS 진단 표본 수를 확인하세요.');Object.assign(diagnostics,{generated:candidates.length,projected:0,matched:0,failed:0,durationMS:0,tests:[],items:[],limit,truncated:false});}
  let rows=[];for(const [index,row]of candidates.entries()){if(diagnostics){row._queryID=index;if(index<diagnostics.limit)retained.set(index,{id:index,actor:row.actor,position:[...row.position],score:0,matched:false,failedTest:null,steps:[]});}const p=await project(row.position);if(p){rows.push({...row,position:p,score:0});const item=retained?.get(index);if(item)item.position=[...p];}else{const item=retained?.get(index);if(item)item.failedTest='projection';}}
  if(diagnostics)diagnostics.projected=rows.length;
  for(const [testIndex,test]of data.tests.entries()){const began=diagnostics?performance.now():0,input=rows.length,values=[];for(const row of rows){const reference=test.reference==='context'?context:origin,d=row.position.map((v,i)=>v-reference[i]),length=distance(d);const value=test.type==='distance'?length:test.type==='height'?d[1]:test.type==='dot'?(length?d.reduce((s,v,i)=>s+(flat&&i===2?0:v*forward[i]),0)/(length*(distance(forward)||1)):0):test.type==='tag'?Number(hasGameplayTag(row.tags,test.tag||'Target')):Number(await trace(reference,row.position)),passed=value>=test.min&&value<=test.max,item=retained?.get(row._queryID);if(item){item.steps.push({test:testIndex,type:test.type,value,passed,score:0});if(!passed)item.failedTest=testIndex;}if(passed)values.push({row,value});}let min=Infinity,max=-Infinity;for(const r of values){min=Math.min(min,r.value);max=Math.max(max,r.value);}rows=values.map(({row,value})=>{const score=(max===min?0:(value-min)/(max-min))*test.weight,item=retained?.get(row._queryID);if(item){item.steps.at(-1).score=score;item.score+=score;}return {...row,score:row.score+score};});if(diagnostics)diagnostics.tests.push({index:testIndex,type:test.type,input,passed:rows.length,failed:input-rows.length,min:values.length?min:null,max:values.length?max:null,durationMS:performance.now()-began});if(!rows.length)break;}
  rows.sort((a,b)=>b.score-a.score||String(a.actor).localeCompare(String(b.actor)));
  if(diagnostics){for(const [rank,row]of rows.entries()){const item=retained?.get(row._queryID);if(item){item.matched=true;item.rank=rank;}}Object.assign(diagnostics,{matched:rows.length,failed:candidates.length-rows.length,durationMS:performance.now()-started,items:[...retained.values()],truncated:candidates.length>retained.size});return rows.map(({_queryID,...row})=>row);}
  return rows;
}
